new PluginReexport([
  {
    entries: ['pages'],
    exclude: /(\.test\.tsx$|\.stories\.tsx$|\.css$)/,
    template({ files }) {
      const pages = files.filter(({ ext }) => ext === '.tsx');
      const exports = pages
        .map(({ name }) => `export const ${name} = lazy(() => import('./${name}'));`)
        .join('\n');

      return `import { lazy } from 'react';\n\n${exports}`;
    },
  },
]),
